export const TRANSLATIONS = { en, id, ms, tr }

export function translate(lang, key, vars) {
  const dict = TRANSLATIONS?.[lang] || en
  let s = dict?.[key] ?? en?.[key] ?? key
  if (vars) Object.entries(vars).forEach(([k, v]) => { s = s.replace(`{${k}}`, v) })
  return s
}

